usage() { cat <<'EOF'
Usage: deploy.sh --env ENV --version SHA [--dry-run] [-v]
  --env ENV       staging | prod           (required)
  --version SHA   git revision to deploy   (required)
  --dry-run       print actions, change nothing
  -h, --help      show this text
EOF
}

target_env="" version="" dry_run=0 verbose=0
while (( $# )); do
  case $1 in
    --env)        target_env=${2:?--env needs a value}; shift 2 ;;
    --version)    version=${2:?--version needs a value}; shift 2 ;;
    --dry-run)    dry_run=1; shift ;;
    -v|--verbose) verbose=1; shift ;;
    -h|--help)    usage; exit 0 ;;
    --)           shift; break ;;
    -*)           usage >&2; exit 64 ;;    # never guess at an unknown flag
    *)            break ;;
  esac
done
: "${target_env:?--env is required}" "${version:?--version is required}"

