import json, os, shlex, subprocess

def run(cmd: list[str], **kw) -> subprocess.CompletedProcess:
    log.debug("exec: %s", shlex.join(cmd))        # shlex.join: Python 3.8+
    return subprocess.run(cmd, check=True, capture_output=True,
                          text=True, timeout=300, **kw)

try:
    r = run(["kubectl", "get", "pods", "-n", ns, "-o", "json"],
            env={**os.environ, "KUBECONFIG": kubeconfig})   # extend, don't replace
except subprocess.CalledProcessError as e:
    raise SystemExit(f"kubectl failed (rc={e.returncode}): {e.stderr.strip()}")
except subprocess.TimeoutExpired:
    raise SystemExit("kubectl timed out after 300s")
pods = json.loads(r.stdout)

# Long output: stream it instead of buffering the whole log in memory.
with subprocess.Popen(["make", "build"], stdout=subprocess.PIPE,
                      stderr=subprocess.STDOUT, text=True) as p:
    for line in p.stdout:
        log.info("build | %s", line.rstrip())
